"""Further campaigns, Axis support and explicit major-power treaty cascades."""
from catalog import *


def append_events():
    if any(e.key == "us_peace" for e in EVENTS):
        return
    independent = "NOT = { alliance = { country = JAP country = GER } }"
    pacific_hold = control(1734)+" "+control(1432,"-3")+" "+control(1565,"-3")+" NOT = { lost_national = { country = JAP value = 5 } } carrier = { value = 6 when = now } OR = { NOT = { carrier = { country = USA value = 5 when = now } } losses = { country = USA type = carrier value = 4 } }"
    eligibility = active()+" "+pacific()+" "+war("USA")+" "+independent+" year = 1943 event = { id = @pacific_open days = 720 } "+pacific_hold
    event("us_peace","Can America accept a Pacific armistice?","After two years of war, secure Hawaii, Singapore and the Philippines and maintain a credible carrier force. America must also have lost substantial carrier strength. Hold that position for six months before terms are offered.\n\nThis is an Allied-Pacific armistice: Britain and other Allied members also leave the war against Japan's bloc. Germany's separate European war continues. Japan must remain outside Germany's alliance. Overseas land outside the named Asian settlement returns to its legal owner.",decision=True,gate=eligibility+" NOT = { flag = JX_US_PENDING flag = JX_US_WAIT flag = JX_US_PEACE flag = JX_US_DISMISSED }",persistent=True,year=1943,actions=[Action("Maintain the position for six months",[flag("US_PENDING"),later("us_hold",180)],chance=100),Action("Wait another six months",[flag("US_WAIT"),later("us_return",180)]),Action("Fight on; dismiss negotiated peace",[flag("US_DISMISSED")])],art="diplomacy",module="usa")
    event("us_hold","A sustained Pacific advantage","The six-month review checks the same military position. If it has been lost, negotiations stop and can be attempted again later. If it remains secure, the American government receives the offer.",triggered=True,actions=[Action("Send the armistice proposal",[later("us_offer",1,"USA")],gate=war("USA")+" "+independent+" "+pacific_hold,chance=100),Action("Rebuild our position before trying again",[clear("US_PENDING"),flag("US_WAIT"),later("us_return",180)],gate="NOT = { "+war("USA")+" "+independent+" "+pacific_hold+" }")],art="diplomacy",module="usa")
    event("us_watch","Pacific negotiations lose their military basis","",gate="flag = JX_US_PENDING NOT = { flag = JX_US_HOLD_BROKEN } NOT = { AND = { "+pacific_hold+" } }",persistent=True,offset=1,actions=[Action("",[flag("US_HOLD_BROKEN")])],module="usa")
    # The watcher invalidates recapture exploits during the six-month hold.
    EVENTS[-2].actions[0].gate += " NOT = { flag = JX_US_HOLD_BROKEN }"
    EVENTS[-2].actions[1].gate = "OR = { flag = JX_US_HOLD_BROKEN NOT = { AND = { "+war("USA")+" "+independent+" "+pacific_hold+" } } }"
    for a in next(e for e in EVENTS if e.key=="us_peace").actions[:1]:
        a.commands.insert(0,clear("US_HOLD_BROKEN"))
    acceptance = [later("us_terms",1,"JAP")]
    refusal = [cond("flag = JX_US_REFUSAL_1",flag("US_REFUSAL_2")),flag("US_REFUSAL_1"),later("us_refused",1,"JAP")]
    event("us_offer","An end to the Pacific war?","Japan offers a Pacific settlement after sustained military success. The proposed armistice concerns the Allied war against Japan and its partners, not the separate European war. Demands are limited to actual Japanese gains and a stated Pacific settlement.",country="USA",triggered=True,actions=[Action("Open negotiations",acceptance,gate="NOT = { flag = JX_US_REFUSAL_2 }",chance=60),Action("Continue the war",refusal,gate="NOT = { flag = JX_US_REFUSAL_2 }",chance=40),Action("Accept negotiations after the repeated defeat",acceptance,gate="flag = JX_US_REFUSAL_2",chance=100)],art="diplomacy",module="usa")
    event("us_refused","America refuses the proposal","America will continue the war. Another offer is possible after six months if the military conditions still hold. After two refusals, maintaining the qualifying position again guarantees negotiations, rather than an endless random refusal loop.",triggered=True,actions=[Action("Prepare for another campaign",[clear("US_PENDING"),flag("US_WAIT"),later("us_return",180)],chance=100)],art="diplomacy",module="usa")
    event("us_return","The Pacific peace option returns","",triggered=True,actions=[Action("",[clear("US_WAIT")])],module="usa")
    event("us_terms","Terms for the Pacific armistice","America will negotiate. Japan keeps agreed Asian conquests and existing partners. Choose to return Hawaii, or retain it as a Japanese base. All other occupied American mainland territory returns to America. Britain and the Allied states end their Pacific war with Japan; Germany's separate war continues.\n\nThe treaty is unavailable if Japan has joined Germany's alliance. No local settlement can make these terms global without saying so.",triggered=True,actions=[Action("Keep the Asian settlement; return Hawaii",[flag("US_RETURN_HAWAII"),later("us_implement",1)],gate=independent+" "+war("USA"),chance=100),Action("Keep Hawaii as well as the Asian settlement",[flag("US_KEEP_HAWAII"),later("us_implement",1)],gate=independent+" "+war("USA")),Action("Reject the terms and continue the war",[clear("US_PENDING"),flag("US_DISMISSED")])],art="diplomacy",module="usa")
    event("us_implement","Implementing the Pacific armistice","",triggered=True,actions=[Action("",[later("us_transfer_USA",0,"USA"),later("us_transfer_ENG",0,"ENG"),later("us_transfer_AST",0,"AST"),later("us_transfer_NZL",0,"NZL"),later("us_transfer_HOL",0,"HOL"),later("us_transfer_FRA",0,"FRA"),later("us_transfer_U05",0,"U05"),later("us_finish",2,"USA")],gate=independent+" "+war("USA"))],module="usa")
    for owner in ("USA","ENG","AST","NZL","HOL","FRA","U05"):
        event("us_transfer_"+owner,"Pacific treaty: territorial clauses","",country=owner,triggered=True,actions=[Action("",[])],module="usa",purpose="Builder supplies the exact checked Asian/island province list. Only owned land currently controlled by Japan transfers.")
    event("us_finish","The Allied-Pacific war ends","The Allied powers and Japan's bloc accept the stated Pacific armistice. The European war and any separate Japanese-Soviet war continue. The treaty does not annex the United States or transfer its surviving army.",country="USA",triggered=True,actions=[Action("Sign the Pacific armistice",[cmd("peace",which="JAP",value=0),cmd("non_aggression",which="USA",where="JAP",when=1800),later("us_signed",2,"JAP")],gate=independent,chance=100)],art="diplomacy",module="usa")
    event("us_signed","The Pacific settlement is in force","The Allied-Pacific war has ended. Japan retains the territories named in the settlement and its existing partners. The German and Soviet wars are governed by their separate diplomatic state. Reconstruction and later treaty choices remain available through 1950.",triggered=True,actions=[Action("Begin the next chapter",[flag("US_PEACE"),clear("US_PENDING"),cmd("dissent",value=-2),later("us_treaty_expiry",1800)],gate="NOT = { "+war("USA")+" }",chance=100),Action("The ceasefire failed; reopen negotiations",[clear("US_PENDING"),flag("US_WAIT"),later("us_return",30)],gate=war("USA"))],art="diplomacy",module="usa")
    event("us_treaty_expiry","The Pacific treaty approaches its end","The five-year non-aggression period is ending. Renew it, or allow ordinary diplomacy to resume. Letting a treaty expire does not automatically declare war.",triggered=True,actions=[Action("Renew the non-aggression agreement",[cmd("non_aggression",which="JAP",where="USA",when=1800)],chance=100),Action("Let ordinary diplomacy resume",[flag("US_TREATY_EXPIRED")])],art="diplomacy",module="postwar")

    event("us_mainland","Demand terms after an American defeat","Japan holds a major Pacific port and America has lost at least 40 percent of its national territory. Existing Blood and Iron defeat terms can now be presented: control of the Pacific, wider withdrawal, a west-coast concession if eligible, or continued conquest. These are national-defeat terms, separate from the limited Pacific armistice.",decision=True,gate=active()+" "+pacific()+" "+war("USA")+" lost_national = { country = USA value = 40 } OR = { "+control(1886)+" "+control(1887)+" "+control(1889)+" } NOT = { flag = JX_US_MAINLAND_OFFERED }",year=1943,actions=[Action("Present the national-defeat terms",[flag("US_MAINLAND_OFFERED"),fire("us_national_terms")],chance=100),Action("Continue the campaign",[flag("US_MAINLAND_OFFERED")])],art="pacific",module="usa")
    # Reserved invasion IDs: us_invasion.apply replaces these definitions with
    # the checked national-surrender sequence after all existing IDs are fixed.
    event("us_national_terms","America: the terms of defeat","",triggered=True,actions=[Action("",[cmd("trigger",which=2011031)])],module="usa")

    sov_gate = active()+" "+pacific()+" "+war("SOV")+" "+independent+" "+control(1191)+" "+control(1190)+" "+control(1169)+" "+control(1162)+" OR = { "+control(1142)+" AND = { "+control(1156)+" lost_national = { country = SOV value = 25 } } } NOT = { flag = JX_SOV_TERMS_DONE flag = JX_SOV_TERMS_WAIT flag = JX_SOV_TERMS_PENDING }"
    event("soviet_terms","Terms after the Siberian campaign","Japan has taken the Far Eastern ports and crossed the eastern railway belt. Novosibirsk, or Krasnoyarsk combined with substantial Soviet losses, makes a serious settlement possible.\n\nA limited eastern peace cedes named occupied Far Eastern provinces and leaves Germany's separate war running. Japan must be outside Germany's alliance. You can keep the ports directly or establish a Far Eastern puppet after the transfer.",decision=True,gate=sov_gate,year=1942,persistent=True,actions=[Action("Seek an eastern settlement; retain the ports",[flag("SOV_DIRECT"),flag("SOV_TERMS_PENDING"),later("soviet_offer",1,"SOV")],chance=100),Action("Seek a settlement and a Far Eastern partner",[flag("SOV_CLIENT"),flag("SOV_TERMS_PENDING"),later("soviet_offer",1,"SOV")]),Action("Continue west; ask again in six months",[flag("SOV_TERMS_WAIT"),later("soviet_terms_return",180)]),Action("Fight to a full Soviet defeat",[flag("SOV_TERMS_DONE")])],art="siberia",module="soviet")
    event("soviet_offer","An eastern armistice with Japan","Japan has sustained a deep Siberian campaign. The eastern terms apply to currently Japanese-held named Far Eastern provinces. Germany's separate war remains active. Refusal allows a later offer; it is not a guarantee of Soviet national surrender.",country="SOV",triggered=True,actions=[Action("Accept the eastern armistice",[later("soviet_land",1,"SOV")],chance=70),Action("Continue the eastern war",[later("soviet_refusal",1,"JAP")],chance=30)],art="siberia",module="soviet")
    event("soviet_land","Soviet-Japanese eastern border agreement","",country="SOV",triggered=True,actions=[Action("",[cond(control(p)+" "+owned(p,"SOV"),cmd("secedeprovince",which="JAP",value=p,when=1)) for p in (1191,1190,1189,1188,1187,1186,1185,1184,1183,1182,1176,1541)]+[cmd("peace",which="JAP",value=0),later("soviet_signed",2,"JAP")],gate=independent)],module="soviet")
    event("soviet_signed","The eastern war has ended","The Soviet war with Japan's bloc has ended; Germany's separate war continues. Japan keeps only the named Far Eastern land it actually held. A client option releases a Far Eastern state with Japanese access. The rest of Siberia is returned under the armistice.",triggered=True,actions=[Action("Put the eastern agreement into effect",[flag("SOV_TERMS_DONE"),clear("SOV_TERMS_PENDING"),cond("flag = JX_SOV_CLIENT NOT = { exists = PRI }",cmd("independence",which="PRI",value=1)),cond("flag = JX_SOV_CLIENT exists = PRI",cmd("make_puppet",which="PRI")),cond("flag = JX_SOV_CLIENT exists = PRI",later("far_east_local",1,"PRI"))],gate="NOT = { "+war("SOV")+" }",chance=100)],art="siberia",module="soviet")
    event("far_east_local","A government in the Far East","The local government grants Japan access and receives a small reconstruction reserve. Its army uses ordinary resources and recruitment.",country="PRI",triggered=True,actions=[Action("Begin reconstruction",[cmd("access",which="JAP"),supplies(1500),cmd("manpowerpool",value=35),cmd("ai",which='"jx/partner_land.ai"'),cmd("build_division",which="infantry",when=3)],chance=100)],art="siberia",module="soviet")
    event("soviet_refusal","Moscow refuses an eastern settlement","The war continues. Another offer becomes possible in six months if the deep campaign requirements still hold.",triggered=True,actions=[Action("Continue the campaign",[flag("SOV_TERMS_WAIT"),later("soviet_terms_return",180)],chance=100)],art="siberia",module="soviet")
    event("soviet_terms_return","The eastern terms can be raised again","",triggered=True,actions=[Action("",[clear("SOV_TERMS_WAIT"),clear("SOV_TERMS_PENDING"),clear("SOV_DIRECT"),clear("SOV_CLIENT")])],module="soviet")

    event("formal_axis","Enter Germany's alliance?","Formal Axis entry shares Germany's existing alliance wars and changes which peace negotiations are possible. Japan can cooperate with Germany, send aid and fight a separate Soviet war without taking this step.\n\nJoining closes the limited Japanese Pacific and eastern armistice offers while this alliance lasts, because alliance-wide peace would include Germany. Check Germany's current wars before confirming.",decision=True,gate=active()+" "+pacific()+" exists = GER NOT = { alliance = { country = JAP country = GER } "+war("GER")+" flag = JX_AXIS_DISMISSED }",year=1941,actions=[Action("Join the Axis and its current wars",[cmd("alliance",which="GER",when=1)],chance=0),Action("Keep the separate Japanese alliance",[flag("AXIS_DISMISSED")],chance=100)],art="diplomacy",module="germany")
    paid_project("axis_fuel","A limited fuel mission for Germany","A submarine shipment consumes 1,000 Japanese oil and delivers 800 to Germany after the mission. Alternatively, send supply support. This is a one-time finite mission, not an open trade route through enemy-controlled oceans.",year=1942,gate=pacific()+" exists = GER oil = 3000 NOT = { "+war("GER")+" }",money_cost=100,supply_cost=1000,days=120,reward=[cmd("oilpool",value=-1000),later("axis_fuel_arrives",1,"GER")],alternative=("Send supplies rather than fuel",[later("axis_supplies_arrive",1,"GER")]),art="diplomacy",module="germany",finish_gate="exists = GER oil = 1000 NOT = { "+war("GER")+" }")
    event("axis_fuel_arrives","Fuel from Japan","A limited Japanese submarine shipment arrives.",country="GER",triggered=True,actions=[Action("Use the delivered fuel",[cmd("oilpool",value=800)],chance=100)],art="diplomacy",module="germany")
    event("axis_supplies_arrive","Japanese supplies arrive","A limited Japanese shipment supports the European war.",country="GER",triggered=True,actions=[Action("Use the delivered supplies",[supplies(1000)],chance=100)],art="diplomacy",module="germany")

    projects = [
        ("ocean_patrol","Reach into the Indian Ocean",1942,pacific(),"Prepare two submarine and two naval-bomber production orders, or two marine orders for base seizures. All use normal IC and manpower.",[cmd("build_division",which="submarine",when=2),cmd("build_division",which="naval_bomber",when=2)],("Prepare amphibious forces instead",[cmd("build_division",which="marine",when=2)]),"naval","campaigns"),
        ("china_expedition","China beyond its own borders",1942,puppet("U87"),"Help the Chinese partner prepare an expeditionary role. A dedicated AI allows limited overseas contributions; alternatively, fund home defence and let China hold its own front.",[later("china_exp_ai",1,"U87")],("Concentrate China on home defence",[later("china_home_ai",1,"U87")]),"army","partners"),
        ("india_expedition","India's place in the wider war",1943,puppet("IND"),"Help India contribute abroad through a limited expeditionary role, or strengthen regional defence and supplies. This is cooperation with a Japanese partner, not the Indian player mod.",[later("india_exp_ai",1,"IND")],("Keep India focused on regional defence",[later("india_home_ai",1,"IND")]),"army","partners"),
        ("island_defence","Build an island defence reserve",1943,pacific(),"Prepare six garrison formations at normal IC cost, or two marine divisions. A mobile reserve costs more operational attention; garrisons release the fleet and best army units for other work.",[cmd("build_division",which="garrison",when=6)],("Prepare another mobile reserve",[cmd("build_division",which="marine",when=2)]),"pacific","units"),
        ("long_range","Aircraft for two oceans",1943,pacific(),"Fund reconnaissance and basing: naval-bomber range improves by 150 km. Or order three multirole wings at normal IC cost to protect forward airfields.",[cmd("range",which="naval_bomber",value=150)],("Build fighters for the forward bases",[cmd("build_division",which="multi_role",when=3)]),"air","air"),
        ("cold_training","Prepare for a Siberian winter",1942,pacific()+" "+war("SOV"),"Train the army for cold operations: five points better frozen movement and defence. Or order three mountain divisions. Neither choice removes winter supply and attrition problems.",[cmd("frozen_move",which="land",value=5),cmd("frozen_defense",which="land",value=5)],("Expand the mountain forces",[cmd("build_division",which="bergsjaeger",when=3)]),"siberia","army"),
        ("fleet_1944","The 1944 naval estimates",1944,pacific(),"Prepare two fleet-carrier construction orders, or four light cruisers and six destroyers. Existing construction discounts are not increased again.",[cmd("build_division",which="carrier",when=2)],("Rebuild cruisers and screens",[cmd("build_division",which="light_cruiser",when=4),cmd("build_division",which="destroyer",when=6)]),"naval","navy"),
        ("china_rebuild","Chinese industrial reconstruction",1942,puppet("U87"),"Fund four Chinese IC, or a larger supply and recruitment reserve. Industry develops in China and does not appear for free in Japan.",[later("china_factories",1,"U87")],("Prioritise army readiness",[later("china_stock",1,"U87")]),"asia","partners"),
        ("india_rebuild","Indian workshops and supply depots",1943,puppet("IND"),"Fund four Indian IC, or larger local supply and recruitment reserves. A useful partner must maintain its own army before trying to build a large navy.",[later("india_factories",1,"IND")],("Prioritise regional military readiness",[later("india_stock",1,"IND")]),"asia","partners"),
        ("reserve_1948","A reserve for an uncertain peace",1948,"atwar = no","Prepare four infantry production orders, or expand home industry by three IC. Choosing a reserve does not declare a war or extend an expired treaty.",[cmd("build_division",which="infantry",when=4)],("Invest in civilian industry",[cmd("construct",which="ic",where=1552,value=3)]),"army","postwar"),
        ("science_1949","Research for the next decade",1949,"","Fund radar and modern carrier-doctrine blueprints, or a modest four-percent national research improvement. The programme remains useful whether the Pacific war ended or continues.",[blueprint(81900),blueprint(8230)],("Support the wider research institutions",[cmd("research_mod",value=4)]),"air","postwar"),
        ("american_base","Supply an American bridgehead",1943,pacific()+" "+war("USA")+" "+control(1887),"Expand the Los Angeles port by two levels and its airfield by two, or order four motorised divisions. The mainland campaign still needs shipping, screens and a defended supply route.",[cmd("construct",which="naval_base",where=1887,value=2),cmd("construct",which="air_base",where=1887,value=2)],("Prepare mobile reinforcements",[cmd("build_division",which="motorized",when=4)]),"pacific","campaigns"),
        ("outer_oil","Persian oil for the fleet",1943,pacific()+" "+control(1089),"Repair the Ahvaz oil facilities, adding five daily provincial oil and improving local infrastructure. Or expand its airfield. The oil must still travel through a real supply and shipping system.",[cmd("add_prov_resource",which=1089,where="oil",value=5),cmd("construct",which="infrastructure",where=1089,value=10)],("Defend the captured facilities from the air",[cmd("construct",which="air_base",where=1089,value=2),cmd("construct",which="flak",where=1089,value=2)]),"industry","oil"),
    ]
    for key,title,year,g,description,reward,alt,art,module in projects:
        paid_project(key,title,description,year=year,gate=g,money_cost=180,supply_cost=1000,days=180,reward=reward,alternative=alt,art=art,module=module,finish_gate=g if key in {"china_rebuild","india_rebuild","china_expedition","india_expedition","american_base","outer_oil"} else "")
    for prefix,tag,cap in [("china","U87",1337),("india","IND",1459)]:
        event(prefix+"_exp_ai","A limited expeditionary agreement","The partner will consider a limited contribution abroad. It keeps most forces for its own defence; an AI preference is not a guarantee that every division embarks immediately.",country=tag,triggered=True,actions=[Action("Prepare a limited contribution",[cmd("ai",which='"jx/partner_expedition.ai"'),supplies(1200)],chance=100)],art="army",module="partners")
        event(prefix+"_home_ai","Defend the partner's home region","The partner concentrates on its own front and local supply.",country=tag,triggered=True,actions=[Action("Strengthen home defence",[cmd("ai",which='"jx/partner_land.ai"'),supplies(1800)],chance=100)],art="army",module="partners")
        event(prefix+"_factories","Workshops for a stronger partner","Four local IC are completed in the partner's controlled capital. If that capital is lost, the funds instead provide a recovery supply reserve.",country=tag,triggered=True,actions=[Action("Open the workshops",[cmd("construct",which="ic",where=cap,value=4)],gate=control(cap,tag),chance=100),Action("Protect the recovery reserve",[supplies(1600)],gate="NOT = { "+control(cap,tag)+" }")],art="industry",module="partners")
        event(prefix+"_stock","A partner's operating reserve","Equipment and recruits support local readiness. This is a finite grant and does not add manpower to Japan.",country=tag,triggered=True,actions=[Action("Prepare local reinforcement",[supplies(1800),cmd("manpowerpool",value=40)],chance=100)],art="army",module="partners")

    # European Axis assistance is finite and only active in the human Japan expansion.
    event("ger_endurance","German mobilisation and fuel planning","",country="GER",year=1941,gate="ai = yes flag = JX_ACTIVE war = { country = GER country = SOV }",actions=[Action("",[cmd("ai",which='"jx/ger_endurance.ai"'),cmd("free_oil",value=12),cmd("manpowerpool",value=150),supplies(1500),later("ger_reserve_2",180,"GER")])],module="axis",purpose="One mobilisation and a modest synthetic-fuel supplement; not a repeatable rescue.")
    event("ger_reserve_2","German reserve mobilisation","",country="GER",triggered=True,actions=[Action("",[cmd("manpowerpool",value=100)],gate="war = { country = GER country = SOV }")],module="axis")
    event("ita_endurance","Italian reinforcement planning","",country="ITA",year=1940,gate="ai = yes flag = JX_ACTIVE war = { country = ITA country = ENG }",actions=[Action("",[cmd("ai",which='"jx/ita_endurance.ai"'),supplies(1800),cmd("oilpool",value=700),cmd("manpowerpool",value=50)])],module="axis")
    africagate = "ai = yes flag = JX_ACTIVE alliance = { country = GER country = ITA } war = { country = GER country = ENG } manpower = 60 supplies = 1500 oil = 1000"
    africa_actions=[]
    for p,prior in [(750,""),(761,"NOT = { "+control(750,"-3")+" }"),(765,"NOT = { "+control(750,"-3")+" "+control(761,"-3")+" }")]:
        africa_actions.append(Action("",[supplies(-1500),cmd("oilpool",value=-1000),cmd("manpowerpool",value=-60),cmd("add_corps",which='"Deutsches Afrika-Korps"',value="land",when=229,where=p),cmd("add_division",which='"Afrika Korps HQ"',value="hq",when=3),cmd("add_division",which='"15. Panzer-Division"',value="armor",when=0),cmd("add_division",which='"5. leichte Division"',value="motorized",when=1),cmd("add_division",which='"90. leichte Division"',value="motorized",when=1)],gate=control(p,"-3")+" "+prior,chance=100))
    event("afrika_ai","A functioning Afrika Korps","",country="GER",year=1941,gate=africagate+" OR = { "+" ".join(control(p,"-3") for p in (750,761,765))+" }",actions=africa_actions,module="axis",purpose="One paid AI expedition to a friendly Libyan port, with four formations. Does not activate the human-only free package.")
    event("finland_support","Equipment reaches Finland","",country="FIN",year=1941,gate="ai = yes flag = JX_ACTIVE war = { country = FIN country = SOV } war = { country = GER country = SOV }",actions=[Action("",[supplies(1500),cmd("manpowerpool",value=35),cmd("frozen_defense",which="land",value=5)])],module="axis")
    event("sov_two_front","The Soviet Union faces two fronts","",country="SOV",year=1941,gate="ai = yes flag = JX_ACTIVE war = { country = SOV country = JAP } war = { country = SOV country = GER } NOT = { local_flag = JX_TWO_FRONT }",persistent=True,actions=[Action("",[cmd("ai",which='"jx/sov_two_front.ai"'),cmd("local_setflag",which="JX_TWO_FRONT")])],module="axis")
    event("sov_west_again","The Soviet eastern front closes","",country="SOV",year=1941,gate="ai = yes local_flag = JX_TWO_FRONT NOT = { war = { country = SOV country = JAP } }",persistent=True,actions=[Action("",[cmd("ai",which='"switch/sov_germany.ai"'),cmd("local_clrflag",which="JX_TWO_FRONT")])],module="axis")


append_events()
